  '#feca57', // pastel yellow
  '#ff7ba7'  // pastel pink
];

// Draw circles with gradient fill
for (let i = 0; i < 6; i++) {
  const radius = maxRadius - i * 30;
  const gradient = ctx.createRadialGradient(
    centerX, centerY,
    radius - 20,
    centerX, centerY,
    radius + 20
  );

  const startColor = colors[i % 6];
  const endColor = colors[(i + 1) % 6];

  gradient.addColorStop(0, startColor);
  gradient.addColorStop(1, endColor);

  ctx.beginPath();
  ctx.arc(centerX, centerY, radius, 0, Math.PI * 2);
  ctx.fillStyle = gradient;
  ctx.fill();
}

// Draw radial patterns
for (let i = 0; i < 8; i++) {
  const angle = (i / 8) * Math.PI * 2;
  const x = centerX + Math.cos(angle) * (maxRadius - 40);
  const y = centerY + Math.sin(angle) * (maxRadius - 40);

  // Draw triangles
  ctx.fillStyle = '#ffffff';
  ctx.beginPath();
  ctx.moveTo(centerX, centerY);
  ctx.lineTo(x, y);
  ctx.lineTo(centerX + Math.cos(angle) * 60, centerY + Math.sin(angle) * 60);
  ctx.closePath();
  ctx.fill();

  // Draw small circles
  ctx.fillStyle = '#000000';
  ctx.beginPath();
  ctx.arc(x, y, 8, 0, Math.PI * 2);
  ctx.fill();
}

