    centerY + Math.sin(angle2) * (maxRadius - 60)
  );
  ctx.stroke();
}

// Cool tones palette for a fractal spiral
const SKY = '#1a1a2e';
const GROUND = '#0f3460';
const ACCENT = '#4ecdc4';
const SHADOW = '#0f1425';
const HIGHLIGHT = '#4a90e2';

// Draw background
ctx.fillStyle = SKY;
ctx.fillRect(0, 0, W, H);

// Draw spiral pattern
function drawSpiral(x, y, r, depth) {
    if (depth > 0) {
        // Draw arc at current position
        ctx.fillStyle = ACCENT;
        ctx.beginPath();
        ctx.arc(x, y, r, 0, Math.PI * 2);
        ctx.fill();

        // Recursive calls for spiral arms
        drawSpiral(x + r, y, r * 0.8, depth - 1);
        drawSpiral(x - r, y, r * 0.8, depth - 1);
        drawSpiral(x, y + r, r * 0.8, depth - 1);
        drawSpiral(x, y - r, r * 0.8, depth - 1);
    }
}

